function About() {
    
    return (
        <div className="max-w-3xl mx-auto p-4 space-y-4">
            <h2 className=" font-bold text-center pt-8 pb-8">About FlaskCart</h2>
            <p>FlaskCart is an open-source inventory and recipe management application designed to help users efficiently manage their kitchen supplies and meal planning. Built with a Flask backend and a React frontend, FlaskCart offers a seamless user experience for tracking ingredients, creating recipes, and organizing shopping lists.</p>
            <p>Whether you're a home cook or a professional chef, FlaskCart provides the tools you need to keep your kitchen organized and your meals delicious.</p>
        </div>
    );
}

export default About;
